// Case 1: ParamType is a reference
template<typename T>
void f(T& param); // param is an lvalue reference

int x = 27;
const int cx = x;
const int& rx = x;

// Call f with various arguments:
f(x);   // T is deduced as int, param's type is int&
f(cx);  // T is deduced as const int, param's type is const int&
f(rx);  // T is deduced as const int, param's type is const int&
        // Note: rx's reference-ness is ignored for T's deduction
